import{_ as l,C as r,c as s,o as n,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Partner levels","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/configuration/partner-levels.md","filePath":"master/sales/crm/configuration/partner-levels.md","lastUpdated":1793789158000}'),i={name:"master/sales/crm/configuration/partner-levels.md"};function h(d,e,c,g,m,v){const a=r("ImagePopup");return n(),s("div",null,[e[0]||(e[0]=t('<h1 id="partner-levels" tabindex="-1">Partner levels <a class="header-anchor" href="#partner-levels" aria-label="Permalink to &quot;Partner levels&quot;">​</a></h1><p>A partner level ranks your contacts, for example Gold, Silver and Bronze. Each level has a weight, a number that says how likely partners of that level are to be given leads. You set the levels once, then assign one to each contact.</p><blockquote><p><strong>In simple words:</strong> A level is a rank with a weight. A higher weight means more leads for that partner.</p></blockquote><p>Open <code>CRM → Configuration → Members → Levels</code>.</p><h2 id="the-level-list" tabindex="-1">The level list <a class="header-anchor" href="#the-level-list" aria-label="Permalink to &quot;The level list&quot;">​</a></h2>',5)),o(a,{src:"/images1/crm/partner-levels-list.png",alt:"Levels list showing Gold 3, Silver 2 and Bronze 1 with their contact counts"}),e[1]||(e[1]=t('<p>The default levels are <strong>Gold</strong> (weight 3), <strong>Silver</strong> (2) and <strong>Bronze</strong> (1).</p><h3 id="views-tabs" tabindex="-1">Views (tabs) <a class="header-anchor" href="#views-tabs" aria-label="Permalink to &quot;Views (tabs)&quot;">​</a></h3><ul><li><strong><em>Active:</em></strong> Levels you can pick. The badge shows how many there are.</li><li><strong><em>Archived:</em></strong> Levels you deleted.</li></ul><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Name:</em></strong> The name of the level.</li><li><strong><em>Level Weight:</em></strong> The weight number.</li><li><strong><em>Contacts:</em></strong> How many contacts have the level.</li></ul><p><strong>Example:</strong> In the dev data, <strong>Gold</strong> has 5 contacts, <strong>Silver</strong> has 6 and <strong>Bronze</strong> has 5.</p><h3 id="search-order-and-export" tabindex="-1">Search, order and export <a class="header-anchor" href="#search-order-and-export" aria-label="Permalink to &quot;Search, order and export&quot;">​</a></h3><ul><li>Type in the search box to find a level.</li><li>Click <strong>Name</strong> or <strong>Level Weight</strong> to sort.</li><li>Drag a row handle to change the order of the levels in the contact form.</li><li>Select rows and use the bulk actions to export, delete, restore or delete for good.</li></ul><h2 id="create-a-level" tabindex="-1">Create a level <a class="header-anchor" href="#create-a-level" aria-label="Permalink to &quot;Create a level&quot;">​</a></h2><ol><li>Go to <code>CRM → Configuration → Members → Levels</code>.</li><li>Click <strong>New Level</strong>.</li><li>Fill in the form.</li><li>Click <strong>Create</strong>.</li></ol>',10)),o(a,{src:"/images1/crm/partner-levels-form.png",alt:"Create Level dialog filled with the name Platinum and Level Weight 4"}),e[2]||(e[2]=t('<ul><li><strong><em>Name:</em></strong> The name of the level. Required. Up to 255 characters.</li><li><strong><em>Level Weight:</em></strong> How likely partners of this level are to be given leads. Required. A whole number, 0 or more. It starts at 1. A weight of 0 means no leads.</li></ul><p><strong>Example:</strong> Name <code>Platinum</code> and weight <code>4</code>. A notice says <strong>Level created</strong>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Where</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Edit</strong></td><td>Active tab</td><td>Changes the name or weight. A notice says <strong>Level updated</strong>.</td></tr><tr><td><strong>Delete</strong></td><td>Active tab</td><td>Moves the level to <strong>Archived</strong>.</td></tr><tr><td><strong>Restore</strong></td><td>Archived tab</td><td>Brings the level back. A notice says <strong>Level restored</strong>.</td></tr><tr><td><strong>Delete</strong> (permanent)</td><td>Archived tab</td><td>Removes the level for good. A notice says <strong>Level deleted</strong>.</td></tr></tbody></table><h2 id="give-a-level-to-a-contact" tabindex="-1">Give a level to a contact <a class="header-anchor" href="#give-a-level-to-a-contact" aria-label="Permalink to &quot;Give a level to a contact&quot;">​</a></h2><ol><li>Open a contact from <code>CRM → Sales → Customers</code>, or from the Contacts app.</li><li>Find the <strong>Partner level</strong> section.</li><li>Choose a <strong>Level</strong>.</li><li>Optional: enter a <strong>Level Weight</strong> for this contact only. Leave it empty to use the weight of the level.</li><li>Save the contact.</li></ol><p>The empty <strong>Level Weight</strong> field shows the weight of the chosen level as a hint. See <a href="./../../../getting-started/contacts/contacts.html">Contacts</a>.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>A contact uses its own weight when you set one. Otherwise it uses the weight of its level. With no level, the weight is 0.</li><li>The <strong>Contacts</strong> column counts the contacts that have the level.</li><li>Archiving a level does not remove it from contacts that already have it.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">CRM configuration</a></li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a></li><li><a href="./../pipeline/manage-sales-teams.html">Manage sales teams</a></li></ul>',11))])}const f=l(i,[["render",h]]);export{p as __pageData,f as default};
